from pathlib import Path

import pandas as pd
import plotly.express as px
import streamlit as st

ROOT = Path(__file__).resolve().parents[2]
RESULTS_DIR = ROOT / "experiments" / "results"

st.set_page_config(
    page_title="Privacy Analysis | HFL-DSE-DP",
    page_icon="🔐",
    layout="wide",
)

st.title("Differential Privacy Analysis")
st.caption(
    "Client-level privacy-accounting results from the recorded HFL-DP experiments."
)

st.warning(
    "Privacy accounting results are presented separately for RDP and PRV. "
    "Do not compare their epsilon values as if they were generated by the same accountant."
)

# ---------------------------------------------------------
# Configuration
# ---------------------------------------------------------

left, right = st.columns(2)

with left:
    accountant = st.selectbox(
        "Privacy accountant",
        ["RDP (historical)", "PRV (reconstructed)"],
    )

with right:
    noise = st.selectbox(
        "Noise multiplier",
        [0.5, 1.0, 1.5],
        format_func=lambda x: f"{x:.1f}",
    )

if accountant == "RDP (historical)":
    filename = f"hfl_dp_final_privacy_noise_{noise:.1f}.csv"
    accountant_description = "Historical RDP accountant results"
else:
    filename = f"hfl_dp_final_privacy_prv_noise_{noise:.1f}.csv"
    accountant_description = "Reconstructed PRV accountant results"

path = RESULTS_DIR / filename

if not path.exists():
    st.error(f"Privacy result file not found: {path}")
    st.stop()

df = pd.read_csv(path)

required = {"domain", "client_id", "epsilon", "delta"}
if not required.issubset(df.columns):
    st.error("The selected privacy CSV does not contain the required columns.")
    st.stop()

df["Domain"] = df["domain"].map({
    "uav": "UAV-IDS",
    "unsw": "UNSW-NB15",
})

df["Client"] = "Client " + df["client_id"].astype(str)
df = df.sort_values(["domain", "client_id"])

# ---------------------------------------------------------
# Privacy budget summary
# ---------------------------------------------------------

max_epsilon = float(df["epsilon"].max())
mean_epsilon = float(df["epsilon"].mean())
delta = float(df["delta"].max())

worst_client = df.loc[df["epsilon"].idxmax()]

st.subheader("Privacy budget summary")

a, b, c, d = st.columns(4)

a.metric("Maximum client epsilon", f"{max_epsilon:.6f}")
b.metric("Mean client epsilon", f"{mean_epsilon:.6f}")
c.metric("Delta (δ)", f"{delta:.0e}")
d.metric("Noise multiplier", f"{noise:.1f}")

st.write(
    f"**Accountant:** {accountant_description}  \n"
    f"**Worst-case client:** {worst_client['Domain']} — "
    f"{worst_client['Client']}  \n"
    f"**Source:** `{filename}`"
)

# ---------------------------------------------------------
# Client epsilon comparison
# ---------------------------------------------------------

st.subheader("Privacy budget across clients")

epsilon_fig = px.bar(
    df,
    x="Client",
    y="epsilon",
    color="Domain",
    barmode="group",
    text="epsilon",
    title=f"Client epsilon — {accountant}, noise {noise:.1f}",
)

epsilon_fig.update_traces(
    texttemplate="%{text:.3f}",
    textposition="outside",
)

epsilon_fig.update_layout(
    xaxis_title="Federated client",
    yaxis_title="Epsilon (ε)",
    legend_title="Domain",
)

st.plotly_chart(epsilon_fig, use_container_width=True)

# ---------------------------------------------------------
# Sample rate relationship (PRV only)
# ---------------------------------------------------------

if accountant == "PRV (reconstructed)":
    st.subheader("Sampling rate and privacy budget")

    if "sample_rate" in df.columns:
        sample_fig = px.scatter(
            df,
            x="sample_rate",
            y="epsilon",
            color="Domain",
            size="n_samples",
            hover_name="Client",
            title="Client sampling rate versus reconstructed epsilon",
            labels={
                "sample_rate": "Sample rate",
                "epsilon": "Epsilon (ε)",
                "n_samples": "Client records",
            },
        )
        sample_fig.update_layout(
            xaxis_tickformat=".1%",
            yaxis_title="Epsilon (ε)",
        )
        st.plotly_chart(sample_fig, use_container_width=True)

        st.caption(
            "Point size represents client record count. "
            "This chart shows an observed relationship, not a causal estimate."
        )

# ---------------------------------------------------------
# Client-level table
# ---------------------------------------------------------

st.subheader("Detailed client privacy records")

display_columns = [
    "Domain",
    "Client",
    "epsilon",
    "delta",
]

if "n_samples" in df.columns:
    display_columns.extend(["n_samples", "sample_rate", "noise_multiplier"])

display_df = df[display_columns].copy()

display_df = display_df.rename(columns={
    "epsilon": "Epsilon",
    "delta": "Delta",
    "n_samples": "Client records",
    "sample_rate": "Sample rate",
    "noise_multiplier": "Noise multiplier",
})

st.dataframe(
    display_df.round(6),
    use_container_width=True,
    hide_index=True,
)

# ---------------------------------------------------------
# Accountant interpretation
# ---------------------------------------------------------

st.subheader("Understanding the privacy accountant")

if accountant == "RDP (historical)":
    st.markdown(
        """
        **Rényi Differential Privacy (RDP)** tracks privacy loss using
        Rényi divergence at different orders and converts the result
        into an approximate \((ε, δ)\)-DP bound.

        These are the historical epsilon values recorded in the original
        experiment result files.
        """
    )
else:
    st.markdown(
        """
        **Privacy Random Variable (PRV)** accounting reconstructs the
        privacy bound from the recorded training configuration and
        sampling information.

        These are reconstructed values and are intentionally displayed
        separately from the historical RDP values.
        """
    )

st.subheader("Research limitations")

st.warning(
    """
    1. The reported accounting is record-level, not client-level differential privacy.
    2. Preprocessing and client construction are outside the stated DP scope.
    3. Historical training used `secure_mode=False`; cryptographically secure
       randomness was not enabled.
    4. The original experiment source version and all training-time provenance
       have not been fully established.
    5. These historical results should not be presented as proof of a
       fully secured, end-to-end formal privacy guarantee.
    """
)

st.caption(
    "Source: experiments/results/" + filename
)
